      "Der Nebel lichtet sich, und das Schiff ist wieder auf Kurs. Wer auf den Nebel gesetzt hatte, hatte nicht mit dir gerechnet.",
      "Im Nebel siehst du nichts durch die Fenster, also schauen alle nach drinnen. Die Aussagen werden sparsamer: Nimm den Bleistift, streiche Felder, die nicht gehen, und schau, was übrig bleibt.",
