      "Im Mai wird das Palais für den Sommer geschlossen, und die Familie zieht aufs Landgut. Noch ein Walzer unter den Kronleuchtern, mit denselben Gesichtern wie an Silvester.",
      "Van Dam setzt seine Pelzmütze auf, verneigt sich vor der Gräfin und steigt in die letzte Kutsche zum Bahnhof. Die Kerzen sind aus, und das neue Jahrhundert hat begonnen. Das letzte Geheimnis des alten hast du gelöst.",
